#!/usr/bin/env node
// Compiles each contract in contracts/ into a standalone validator module (Ajv standalone code),
// written to src/generated/validators/<contract>.js. These run inside n8n Code nodes, where Ajv
// itself and local files aren't available (D-014). Regenerate after any schema change:
//   node scripts/build-validators.js            (writes)
//   node scripts/build-validators.js --check    (exits 1 if the generated files are stale)
const fs = require('node:fs');
const path = require('node:path');
const Ajv2020 = require('ajv/dist/2020');
const standalone = require('ajv/dist/standalone').default;
const { ROOT } = require('./lib/env');
const { CONTRACTS, CONTRACTS_DIR } = require('../src/validate');

const OUT = path.join(ROOT, 'src', 'generated', 'validators');

function build() {
  // allErrors: false keeps the code small; n8n only needs valid/invalid plus the first error.
  const ajv = new Ajv2020({ allErrors: false, strict: true, allowUnionTypes: true, strictRequired: false, code: { source: true, lines: true } });
  for (const f of fs.readdirSync(CONTRACTS_DIR).filter((x) => x.endsWith('.schema.json'))) {
    ajv.addSchema(JSON.parse(fs.readFileSync(path.join(CONTRACTS_DIR, f), 'utf8')), f);
  }
  const files = {};
  for (const name of CONTRACTS) {
    const schemaVersion = JSON.parse(fs.readFileSync(path.join(CONTRACTS_DIR, `${name}.schema.json`), 'utf8')).properties.schema_version.const;
    const code = standalone(ajv, ajv.getSchema(`${name}.schema.json`));
    files[`${name}.js`] = `// GENERATED by scripts/build-validators.js from contracts/${name}.schema.json (schema_version ${schemaVersion}). Do not edit.\n${code}\n`;
  }
  return files;
}

if (require.main === module) {
  const files = build();
  const check = process.argv.includes('--check');
  let stale = 0;
  if (!check) fs.mkdirSync(OUT, { recursive: true });
  for (const [file, code] of Object.entries(files)) {
    const target = path.join(OUT, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (current === code) continue;
    stale++;
    if (check) console.log(`stale: src/generated/validators/${file}`);
    else { fs.writeFileSync(target, code); console.log(`wrote src/generated/validators/${file}`); }
  }
  if (check && stale) process.exit(1);
  if (!stale) console.log('validators up to date');
}

module.exports = { build };
